INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0WR2BRK1BN38AEMTQ3N2W2Q', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'LTVera Ask-Code', 'active', NULL, NULL, 'Cross-repository delivery of authenticated Slack Ask-Code answers about the LTVera codebase. AEGIS production registration is complete; LTVera must refresh and deploy its RAG index/service, then record end-to-end acceptance evidence in the shared tracker.', 'An authorized user receives a readable, current, source-cited answer to @Sleuth ask-code ltvera <question>; authenticated LTVera smoke and Slack happy-path plus safe failure-path evidence are recorded in BinoidCBD/LTVera-Pandas issue 212.', 'ref-01M0WR2BRNETC2NBNR71TTBVEH', NULL, NULL, NULL, 'No', 'No', 'No', NULL, NULL, NULL);
INSERT INTO releases(global_id, repo_gid, version, codename, status, target_date, shipped_date, description, exit_criterion, tracking_ref_gid, marathon_gid, gh_release_url, milestone, front_door_reviewed, shakedown_reviewed, license_file, baseline_count, baseline_at, baseline_source) VALUES('rel-01M0Y1MXPSR7TC8VD7PFNRAHJJ', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, '"Retrospect"', 'draft', NULL, NULL, 'Successor to Confluence (#80, frozen 2026-08-17) — new attachment-resolution scope spun off here instead of reopening that manifest.', NULL, 'ref-01M0Y163MWWEW7CPNZ7BPPTJF4', NULL, NULL, 'Reference-aware attachment resolution: OCR and text-context analysis reach into thread history, not just the current message.', NULL, NULL, NULL, NULL, NULL, NULL);
