INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '126', '  no longer what it is. GH-22 (multiple reminder assignees), the only user-visible defect');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '127', '  it carried, SHIPPED in 1.4.264 via PR #29 and is closed. What remains is entirely tooling');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '128', '  — four checks and one script that are broken in a way which makes OTHER problems harder');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '129', '  to see. That is now the whole point of the release, so the milestone reads honestly.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '130', '  The unifying defect: a check that is always red, always warning, or silently skipping');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '131', '  teaches people to ignore it, and then it can never signal the condition it exists for.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '132', '  GH-39 (`validate:commands` permanently red on development — ask-reminders is registered');
