INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '138', '  GH-26 (RELEASES.md <!--test--> fixture errors every releases check, plus Codename');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '139', '  absorbed by the preceding block) is the highest-leverage of the four and is this');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '140', '  release''s anchor: it is what keeps `pdda.sh releases` from ever reaching errors=0, which');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '141', '  in turn skips `pdda-doc-ready` ENTIRELY. Note that `utils/pdda/*` is synced from a');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '142', '  canonical PDDA repo, so the fix must be pushed upstream or the next `pdda-sync.sh push`');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '143', '  overwrites it. GH-25 (sanitize-scan.sh cannot run from a linked git worktree —');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '144', '  `[ -d .git ]` is false when .git is a file) blocks running the secret/PII gate locally');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4KMFQ8KXASJJK02WB', '145', '  before pushing; CI is unaffected, so the cost is a slower feedback loop, not an exposure.');
