INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '178', '  128 of 216 scheduled messages (60%) log actionable_span_ratio=0 — the analyzer quoted NO');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '179', '  actionable span for the message it had just decided to schedule. 48 of those are 400+');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '180', '  characters; the largest is 6998. On every one of them the GH-43 buried-task gate is inert');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '181', '  by design, because a zero ratio is absence of evidence rather than evidence of a buried');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '182', '  task, so a very long note routes on sentence count alone.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '183', '  What already shipped, and why it is NOT this: GH-43 (1.4.273-274) fixed synthesis routing');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '184', '  and ownership; GH-51 (1.4.277) fixed a rounding defect where toFixed(2) collapsed any span');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '185', '  under 0.5% of the message to exactly 0, hiding the most deeply buried task of all. That');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '186', '  rounding fix is real but explains AT MOST 1 of the 128 — the median zero-ratio message is');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '187', '  241 characters, where nothing rounds away. The remaining ~127 are the analyzer returning an');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '188', '  empty actionable_language. The schema already requires the field (strict: true), so the');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '189', '  model is satisfying presence with "", and OpenAI strict mode has no minLength to forbid it.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '190', '  Deliberately NOT started by editing reminders-instructions.md on a hypothesis. The decision');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '191', '  corpus wired in GH-50 (1.4.276) exists precisely so this can be diagnosed from real');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '192', '  input/output pairs rather than guessed at — but it is default-OFF and carries raw tenant');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '193', '  text with no rotation, cap, or expiry, so a retention policy is a hard prerequisite before');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '194', '  it is armed anywhere real. That policy is currently unowned and unfiled.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '195', '  Done when: the ratio=0 share is explained with evidence rather than inference (schema,');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '196', '  prompt, structural path, or a measurement bug); any extraction defect found is fixed with a');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0V7FVJ4ZFWJ1K27PBGPH4AY', '197', '  regression test built from real production shapes; and the share is re-measured on');
