INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYFQWWVV2Q8W5Z2ZH4', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'P2 snapshot→Slack relay', 'In progress', '13', NULL, NULL, NULL, NULL, 'PROJECT/2-WORKING/P2-SNAPSHOT-SLACK-RELAY.md', NULL, '- **P2 snapshot→Slack relay** — forwards `/snapshot` output into private `#repo-snapshots` via Sleuth. **Re-verified live 2026-07-17 via direct SSH to prod** (commit 0615d427/v1.4.232, service running current code): `SNAPSHOT_RELAY_WORKSPACES=neochrome` → channel `C000EXAMPLE3` (#repo-snapshots), the only enabled workspace/channel pair. **Live bug found (not fixed here):** the file-attachment path has failed with `missing_scope` on every attempt since at least 2026-06-18 (~1 month) — the text summary always posts, the actual snapshot content never has. Needs a Slack app admin to re-grant the bot''s file-upload scope. → [PROJECT/2-WORKING/P2-SNAPSHOT-SLACK-RELAY.md](PROJECT/2-WORKING/P2-SNAPSHOT-SLACK-RELAY.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYK5Z04MPB6NNZGSFX', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, '"Make Sleuth smart" marathon (GH-360 / GH-361 / GH-362)', 'In progress', '14', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-361-CONNECT-THE-DOTS.md', NULL, '- **"Make Sleuth smart" marathon (GH-360 / GH-361 / GH-362)** — a 6-lane marathon that ends the "compute → render → discard" pattern: stamp client/project identity at creation + operator-defaults config (**#361 A**), `ask-reminders` over live authoritative data (**#361 B**), whole-thread multi-task inference (**#360**), durable deterministic-first project map (**#361 C**), deterministic proactive digest signals (**#362 P1**), then **p6 — an end-to-end net-improvement acceptance test** (`tests/marathon-360-361-362-e2e.test.js`) proving p1-p5 actually connect (data one phase persists is data a later phase reads), not just that each ships in isolation. Cross-model consult (Codex + agy) adjudicated + folded in. Ordered dependency chain, not a concurrency wave. **SHIPPED + merged to main 2026-07-13 (`marathon.complete`, v1.4.212 line); docs closed out to `3-COMPLETED` 2026-07-14.** All 6 lanes green incl. p6 e2e. **Caveat:** only GH-362 **Phase 1** shipped; GH-362 Phases 2 & 3 deferred → **GH-366** (in progress, `feat/gh-366-proactive-phases-2-3`). → [GH-361](PROJECT/3-COMPLETED/GH-361-CONNECT-THE-DOTS.md) · [GH-360](PROJECT/3-COMPLETED/GH-360-MULTI-MESSAGE-INFERENCE.md) · [GH-362](PROJECT/3-COMPLETED/GH-362-PROACTIVE-LAYER.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
