INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRY4522X3PM1H95QN6K', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Admin-facing DM reminders kill switch (GH-413)', 'Queue / parked intake', '8', NULL, NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-413-DM-REMINDERS-KILL-SWITCH.md', NULL, '- **Admin-facing DM reminders kill switch (GH-413)** — GH-412 follow-up, deliberately deferred, not
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYZ3SM4WNPK3GNBYHC', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Needle first-responder router spike (GH-392)', 'Queue / parked intake', '9', '⏸️', NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-392-NEEDLE-ROUTER-SPIKE.md', NULL, '- **Needle first-responder router spike (GH-392)** — **⏸️ DEFERRED, gated on GH-397 / PR #401 (Gemini Flash Lite router = the primary router POC).** Flash Lite is built, needs no new infra, and its shadow-store is the eval harness Needle would reuse. **Re-trigger:** only when (1) #401''s shadow data shows the routing tier is worth activating AND (2) a privacy/cost/offline driver makes local inference matter — then evaluate Needle as the local-tier alternative *on #401''s harness*, not a second rig. Original plan below. Evaluate cactus/Needle (26M ARM on-device tool-calling model) as Sleuth''s cheap/local first-responder router, with confidence-based handoff to the main LLM. **Phase 0 = go/no-go technical spike**: build a golden-routing eval set from real traffic, baseline the current main-LLM router, stand Needle up on OCI Always Free Ampere A1 (`cactus serve`), and shadow-diff the two — Needle gets zero authority. GO only if Needle+handoff ≥ baseline at acceptable latency/RAM. **NO-GO still ships the golden-routing eval set as a PDDA-gated regression suite** (the model-agnostic fix for convention drift, cf. #391). Complements the structural guards (GH-387/388/391). Build via /relay, not a solo session. Captured via /idea. Issue [#392](https://github.com/NeochromeTeam/sleuth-app/issues/392). -> [PROJECT/1-INBOX/GH-392-NEEDLE-ROUTER-SPIKE.md](PROJECT/1-INBOX/GH-392-NEEDLE-ROUTER-SPIKE.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYY8E45ZZXJ25M25AZ', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Router shadow corpus — Flash Lite candidate #1 (GH-397)', 'Queue / parked intake', '10', NULL, NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-397-FLASH-LITE-ROUTER-SHADOW.md', NULL, '- **Router shadow corpus — Flash Lite candidate #1 (GH-397)** — **same experiment as #392**, cheapest candidate: shadow-log every `@Sleuth` routing decision (matched AND unmatched) to a separate non-authoritative per-workspace JSONL corpus, then replay Flash Lite / Needle / an embedding tier / a local 0.5B **offline** against it. The **corpus** (a replayable, labeled routing regression set) is the durable deliverable; Flash Lite is just the first model run against it. Integration is near-zero — `gemini-*` already routes to `gemini-provider.js` (which strips the schema keys Gemini rejects), `GEMINI_API_KEY` is already a validated workspace field, and the fire-and-forget unmatched-mention hook (`#EmitNearMissProbeAsync`) already exists. **Load-bearing risk:** the near-miss Phase 0 readout saw only ~2 failures / 6wk on `neochrome`, so shadowing matched inputs (false-alarm/agreement metrics) is non-optional and the window is record-count-timeboxed. Shadow-only, zero authority, tenancy-gated (`NEOCHROME_TEAM_ID`) + kill-switched (`ROUTER_SHADOW_ENABLED`); `rawText` capture is a privacy escalation to scope + retention-bound. **#397 gates #392** — it''s the low-hanging-fruit experiment that decides whether Needle is worth pursuing. **Operator-locked scope (2026-07-16):** ship a per-workspace three-state **router mode** `off | shadow | active` now, flipped live by an admin-only `@Sleuth AI router-mode <mode>` Slack command (in-memory, resets to `off` on restart). `shadow` logs the corpus; `active` = Flash Lite **full takeover** above a confidence threshold (incl. Risk-tagged commands, operator''s call), else falls back to the current resolver. **SHIPPED and ACTIVE on prod, scoped to `neochrome` (as of v1.4.232+):** router-mode command, sticky mode across restarts (`ROUTER_SHADOW_DEFAULT_MODE`), pinned stable model (`gemini-3.1-flash-lite`), and `models`-command surfacing all landed — see CHANGELOG for the full list. Issue stays open: the corpus itself is an ongoing data-collection deliverable, not a discrete one-shot fix — re-evaluate #392 (Needle) once enough shadow data accumulates. Issue [#397](https://github.com/NeochromeTeam/sleuth-app/issues/397). → [PROJECT/1-INBOX/GH-397-FLASH-LITE-ROUTER-SHADOW.md](PROJECT/1-INBOX/GH-397-FLASH-LITE-ROUTER-SHADOW.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYJMERSXQHD7FNMEAA', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Proactive layer Phases 2 & 3 (GH-366)', 'Queue / parked intake', '11', NULL, NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-366-PROACTIVE-PHASES-2-3.md', NULL, '- **Proactive layer Phases 2 & 3 (GH-366)** — deferred remainder of GH-362 (Phase 1 shipped p5). **P2:** learned-convention proposals (propose-and-confirm, no LLM) — mine completion history for assignee/cadence concentration, propose operator-gated config edits with evidence. **P3:** dropped-thread watch — deterministic prefilter records unanswered client-channel questions; LLM classifies at digest time only; one-tap convert to a reminder. Both ride the existing digest under the ≤3/day cap. **P2.1 (deterministic proposal core) + P2.2 (suppression + rate-limit store) shipped 2026-07-17 in v1.4.235** (24/24 tests green); P2.3 (digest wiring), P2.4 (confirm/decline actions), and Phase 3 remain — P2.3 needs its own preflight contract before it''s marathon-ready. → [PROJECT/2-WORKING/GH-366-PROACTIVE-PHASES-2-3.md](PROJECT/2-WORKING/GH-366-PROACTIVE-PHASES-2-3.md) · [design](PROJECT/3-COMPLETED/GH-362-PROACTIVE-LAYER.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYWWR0N8SG2T4VD4QR', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'P3 event-sourced core (event ledger)', 'Queue / parked intake', '12', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/P3-EVENT-SOURCED-CORE.md', NULL, '- **P3 event-sourced core (event ledger)** — **COMPLETE / closed out 2026-08-09.** Phases 0–3 delivered: dual-write ledger, `summarize-week` projection, and the entity-linking read-model (additive by design — nothing in `src/` imports it). **The read cutover is PARKED BY DECISION, not pending.** Generation-binding of the coverage marker was falsified — a crashed append writes nothing to the ledger, so no ledger-derived quantity distinguishes "never attempted" from "attempted and lost", which means a coverage marker can never certify the completeness that serving a projection requires. The two read surfaces were also judged to gain migration confidence but no latency or scale benefit. The ledger is retained as a **non-authoritative projection/research substrate** — not audit-grade, not a deferred authority migration. All four projection flags (`REMINDERS_READ_SOURCE`, `COMPLETED_READ_SOURCE`, `REBALANCE_EXPORT_SOURCE`, `SUMMARIZE_WEEK_COMPLETED_SOURCE`) are blocked in code and set to `authoritative` on both servers; re-opening the authority path needs a named product consumer and a fresh proposal, deliberately not a config edit. Release `1.5.0` "Ledger" is retired as a goal post — the finish line moved from "flip the flag" to "decide what the ledger is for", and it did. Residual items are deferred with explicit revival triggers in the plan doc''s section D; none is a live defect. → [PROJECT/3-COMPLETED/P3-EVENT-SOURCED-CORE.md](PROJECT/3-COMPLETED/P3-EVENT-SOURCED-CORE.md) · [GH-35](https://github.com/HiQS-Suite/aegis-sleuth-slack-bot/issues/35) · [RELEASES.md](RELEASES.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRY51GQ4TZSVPKTA7CH', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'P3 event schema expansion (v2)', 'Queue / parked intake', '13', NULL, NULL, NULL, NULL, 'PROJECT/2-WORKING/P3-EVENT-SCHEMA-EXPANSION.md', NULL, '- **P3 event schema expansion (v2)** — the schema-expansion proposal the entry above says Phase 4 needs before any retry. **Phases A/B delivered and C''s field gate + generation-aware coverage checkpoint delivered** (`marathon/p3-phase5-read-cutover-2026-08-08`, PR #31): versioned append validation selected by the event''s own `v` so v1 streams read unchanged, complete transition-emission coverage, thread-scoped relay events, `--enrich`/`--retire-orphans` backfill, and a durable per-workspace coverage marker that keeps a projection from serving when an append failed or nothing has ever been verified. **Phase D ran against a copy of live `neochrome` and found three defects no review caught** — removal was never evented (11 reminders would have been resurrected into Slack), imported completions were dropped from both read models (32 of 152 lost), and backfill only ran in one direction. All fixed; real-data read-model parity is now 23/23 active and 152/152 completed. **Operator sequence is `--enrich --retire-orphans` → compaction → re-verify**, since enrich alone leaves strict rejecting historical v1 transition events. **Every projection flag remains BLOCKED** pending a production run. → [PROJECT/2-WORKING/P3-EVENT-SCHEMA-EXPANSION.md](PROJECT/2-WORKING/P3-EVENT-SCHEMA-EXPANSION.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRY9MT0PQX0784EEGMT', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'First-time-user UX', 'Queue / parked intake', '14', NULL, NULL, NULL, NULL, 'PROJECT/2-WORKING/FIRST-TIME-USER-REMEDIATION.md', NULL, '- **First-time-user UX** — live question-battery baseline captured (2026-06-21, real LLM). Phase 0.5 metric finalized against real prod data (2026-07-05); **Phase 1 (Q5/Q1 quick wins) is now marathon-ready** with a swarm preflight contract — SOLO lane (reminder-display cluster, serializes after GH-338). Phase 2 held; Phase 3 held (near-miss readout shows 0 reminder-create dead-ends in 6 weeks; needs probe enrichment first). → [remediation](PROJECT/2-WORKING/FIRST-TIME-USER-REMEDIATION.md) · [question battery](PROJECT/2-WORKING/FIRST-TIME-USER-QUESTION-BATTERY.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYP2SMAG0D1FGMQEXP', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Admin bug-report reaction (GH-358)', 'Queue / parked intake', '15', NULL, NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-358-BUG-REPORT-REACTION.md', NULL, '- **Admin bug-report reaction (GH-358)** — new, independent 🐛 reaction on Sleuth''s own messages files a GitHub issue (extracted shared filing helper), confirms in-thread with the issue link, and logs to a reminders-shaped local store. **Phase 1 shipped 2026-07-09** via the marathon swarm (codex builder + agy reviewer) — corrected two spec deviations (title truncation, confirmation message text) and a `checkJs` type-narrowing regression the scoped gate missed, added 6 regression tests (none shipped with the lane); full suite green (1207/1207). Phases 2 (wastebasket integration), 3 (`show-bugs`), 4 (`refresh`) not started. → [PROJECT/1-INBOX/GH-358-BUG-REPORT-REACTION.md](PROJECT/1-INBOX/GH-358-BUG-REPORT-REACTION.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
