INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYZYKZWJ7FGTQWWMNM', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'GitHub relay leaks unrelated follow-ups onto a linked issue (GH-37)', 'Completed', '9', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-37-RELAY-RELEVANCE-GATE.md', NULL, '- **GitHub relay leaks unrelated follow-ups onto a linked issue (GH-37)** — **shipped to `development` via PR [#38](https://github.com/HiQS-Suite/aegis-sleuth-slack-bot/pull/38) (`3dfb59b`); issue [#37](https://github.com/HiQS-Suite/aegis-sleuth-slack-bot/issues/37) closed; deployed to the Vultr dev server.** The relay gated purely on thread structure, so once any reminder in a thread carried a GitHub URL every later reply was commented onto that issue — observed live when a new, unrelated task ("fix NN Yard IDs") landed on GH 18''s countdown-reminder issue and was deleted by hand. Each linked reminder is now scored independently by a `github-relay-relevance` prompt pair through a new shared `src/ai-decision.js` helper (also adopted by the existing dedup call, behavior-identically), and the comment goes only to reminders clearing `relay` at `confidence >= 0.7`, fail-closed. Scoring per reminder rather than per message also fixed the fan-out half, where a two-issue thread copied every reply onto both. Adding the 🐙 reaction now stops a thread''s relay — the emoji the bot already leaves is the one you click — guarded so the bot''s own acknowledgement cannot stop the relay it just started. **Two QA rounds:** agy on the feature (its one blocker, "the reaction handler is untested", was rejected on evidence — 11 passing tests), then Codex on the merge with development''s event schema v2, which landed on the same class concurrently. Codex found a genuine **blocker**: narrowing the relay-started write to the gate-filtered subset recreated the ledger/JSON parity divergence `reminders-projection.js:533-554` documents, since that fold applies thread-scoped state to every reminder. Also fixed a stop-path ordering defect where a failed Slack acknowledgement left the store stopped and the ledger silent. Both carry mutation-verified regression tests. → [PROJECT/3-COMPLETED/GH-37-RELAY-RELEVANCE-GATE.md](PROJECT/3-COMPLETED/GH-37-RELAY-RELEVANCE-GATE.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYKQ83BP4DGS32R006', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Thread-reply reminder deduplication (GH-27)', 'Completed', '10', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-27-THREAD-REMINDER-DEDUP.md', NULL, '- **Thread-reply reminder deduplication (GH-27)** — **shipped to `development` as squash commit `5a148c7` (PR [#28](https://github.com/HiQS-Suite/aegis-sleuth-slack-bot/pull/28)), issue [#27](https://github.com/HiQS-Suite/aegis-sleuth-slack-bot/issues/27) closed.** An incidental `today` in a later thread reply scheduled the same root-thread task a second time, because the exact-`OriginalMessageID` fast path returned `schedule` unconditionally on a miss — leaving the semantic comparison behind it **unreachable dead code**. The fix derives a thread identity (`OriginalThreadTs ?? OriginalMessageID`) and runs semantic comparison only across reminders sharing it, preserving distinct follow-up work and the zero-extra-AI path for unrelated threads. Reviving that dormant path had a non-obvious side effect caught in review: `CheckForDuplicateReminderAsync` is also called by the **force-schedule escape hatch**, so an AI verdict could suddenly veto an explicit user override — a branch with no test coverage at all. Closed by tagging every dedup exit with `matched_by` (`''message_id'' | ''semantic'' | null`) and gating the force branch on `''message_id''` only, restoring the pre-existing contract exactly rather than inventing a new one; two regression tests now drive both force-schedule outcomes through the alarm-clock reaction path. Verified 1,518 Jest + 33 Node green, typecheck clean. → [PROJECT/3-COMPLETED/GH-27-THREAD-REMINDER-DEDUP.md](PROJECT/3-COMPLETED/GH-27-THREAD-REMINDER-DEDUP.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYZEZNSQKB28ZJ22MR', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Multiple reminder assignees (GH-22)', 'Completed', '11', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-22-MULTIPLE-REMINDER-ASSIGNEES.md', NULL, '- **Multiple reminder assignees (GH-22)** — **shipped to `development` via PR [#29](https://github.com/HiQS-Suite/aegis-sleuth-slack-bot/pull/29) (squash `9d7e319`); issue [#22](https://github.com/HiQS-Suite/aegis-sleuth-slack-bot/issues/22) closed.** A reminder naming two people was persisted and indexed for only the first mention while its confirmation named both, so the second person''s `show-me` silently omitted it. One shared record now carries an additive authoritative `AssigneeIDs` array with legacy `AssigneeID` kept as a first-value mirror and normalized on load, so old records stay readable and a rollback stays a flag flip. **The instructive part is where the bug actually lived:** the marathon''s p1 lane built the whole contract — normalization, multi-mention scheduling, per-assignee display, per-user Slack List fan-out — across two automated rounds, and never fixed the reported symptom, because the singular `AssigneeID === userId` compare causing it sat in `src/chat-commands/show-me-context.js`, *outside the plan''s declared artifact paths*. No lane could touch it; the reviewer identified it and authorized the scope expansion in the same turn a `timeout-gate-failed` escalation killed the phase. Finished by hand: membership now resolves through the canonical `RemindersModule.IsAssignedTo` (deferred require — a top-level import closes a `reminders-module → connection-surfacing → reminder-clustering → show-me-projects-command` cycle), plus the two tests the reviewer asked for, **both verified to fail against the pre-fix code before being accepted**. Also restored the single-assignee confirmation copy, which the builder had reworded to "scheduled as shared work for" for *every* reminder against an explicit brief prohibition. Event-log compatibility verified rather than assumed: `FoldReminders` reads only the singular `assigneeId`, still emitted alongside the additive array, so historical `summarize-week` output is unchanged. Gates: 94/94 suites, 1524 Jest + 33 Node, `validate:fsm` OK, `tsc` clean. **Surfaced a separate standing conflict** — this was the first change ever to push a `phases/*/RELAY.md`, and CI''s sanitize gate rejected it on 9 `absolute-local-path` findings; `ef45021` tracks those files because marathon-drive HALTs without them, so every pushed marathon phase will reproduce this until the harness renders repo-relative paths. → [PROJECT/3-COMPLETED/GH-22-MULTIPLE-REMINDER-ASSIGNEES.md](PROJECT/3-COMPLETED/GH-22-MULTIPLE-REMINDER-ASSIGNEES.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRY5MYDC5QPAB0AV08W', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Durability hardening (GH-12)', 'Completed', '12', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-12-DURABILITY-HARDENING.md', NULL, '- **Durability hardening (GH-12)** — **shipped 1.4.261, all 6 phases agy-QA''d (PR [#13](https://github.com/HiQS-Suite/aegis-sleuth-slack-bot/pull/13)).** The authoritative JSON stores wrote via plain `fs.writeFile` — truncate-then-rewrite, no temp file, no atomic rename, **zero `fsync` call sites in `src/`** — so a hard kill mid-write left unparseable JSON, every loader degraded that to "start empty", and `#DataLoaded` **did not guard saves**, making the loss permanent on the next ordinary write. Phase 0 re-ranked the tiers against `HONEST.md:128`, which named the wrong two subsystems: the **reminder queue** (10 call sites) was the biggest blast radius and wasn''t listed, while the **event ledger was the safest**. Fix: one shared `src/durable-write.js` (temp → `fsync` → rename → `fsync` dir, unique per-write temp names), adopted by every authoritative writer, **plus** a per-store write chain — atomic rename orders nothing, and the lost-update race dropped **3 of 8** completed reminders with serialization bypassed — plus a quarantine guard so a corrupt load is renamed aside rather than overwritten. Verified by a crash-injection harness whose `unsafe` control must reproduce damage or the run self-fails: at N=100 per write shape, whole-file async **23 → 0** corrupt, whole-file sync **3 → 0**, JSONL append **0 → 0** (append confines damage to the tail by construction). The harness caught *itself* twice — a clean control, then a false 35/100 — and neither fault was in the source. Cost measured not assumed: `fsync`-per-append is 57× relative but **571 ms/day**, and the intuitive fd-holding optimization was refuted at ~10% and rejected. `HONEST.md`/`README.md` re-truthed to exactly what was measured — **Say with care**, "survives a hard kill without corrupting its stores", explicitly *not* "crash-proof"/"zero data loss" since `SIGKILL` cannot empty the page cache; **the "not load-tested" claim was left untouched.** Issue [#12](https://github.com/HiQS-Suite/aegis-sleuth-slack-bot/issues/12). → [PROJECT/3-COMPLETED/GH-12-DURABILITY-HARDENING.md](PROJECT/3-COMPLETED/GH-12-DURABILITY-HARDENING.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRY2DA74M8JCAKH9C9S', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Unresolved Slack mentions + blank permalink in filed bug reports (GH-428, GH-429, GH-430)', 'Completed', '13', NULL, NULL, NULL, NULL, NULL, NULL, '- **Unresolved Slack mentions + blank permalink in filed bug reports (GH-428, GH-429, GH-430)** — a `:bug:`-filed GitHub issue (GH-428) showed raw `<@U...>` mentions instead of names in its title/body, and its "View Slack message" link rendered a blank page. Fixed: new `src/slack-message-pipeline.js` (`ResolveMentionsForExternalDisplayAsync`) — the seed of an aspirational unified "make Slack text safe to read outside Slack" pipeline (GH-429, more call sites deferred) — wired into the bug-report and thread-capture flows; `GetPermaLinkAsync` now builds its own canonical archive URL instead of trusting Slack''s `chat.getPermalink` response verbatim, sidestepping its occasional redir-wrapped auth-bounce form (GH-430). 16 new regression tests, shipped 1.4.242. **Follow-up (1.4.243):** operator-requested headless Codex `relay-xyz` review of GH-429 for DRY/quality caught 3 real issues — a duplicate-lookup inefficiency (no cross-message cache in `thread-memory.js`) and a mention-token regex independently re-derived in 3 files — all fixed; `SlackFormatUtils` is now the one owner of the mention grammar (`ExtractUserMentions` + new `ReplaceUserMentions`). **Follow-up 2 (1.4.244, GH-432):** `/consult`-validated migration of the pipeline to `github-comment-relay.js` (same GH-428 bug class in relayed GitHub PR/issue comments, plus a separate raw-fallback bug in the author name); confirmed web-api''s dashboard export and Slack Lists don''t need it. Caught a 3rd missed regex copy in `web-api.js` along the way. Filed **#433** (unrelated Lists piped-mention Block Kit bug, found during the consult, deliberately not fixed here) and a comment on [xyz-3-agents-swarm#296](https://github.com/Claude-AI-Tools-Ventura-County/xyz-3-agents-swarm/issues/296) (relay-drive.sh worktree-isolation path bug hit while QA''ing GH-429, plus a new token-poisoning-on-self-recovery detail). → [CHANGELOG.md](CHANGELOG.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYZCY2T5ADWHSW52W8', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, '"above" thread-reference not resolving into the reminder title (GH-424)', 'Completed', '14', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-424-ABOVE-CONTEXT-SYNTHESIS.md', NULL, '- **"above" thread-reference not resolving into the reminder title (GH-424)** — v1.4.239''s verb-widening fix (`follow\s+(?:up\s+)?on`) turned out insufficient — "please see above" reproduced the same symptom same day. v1.4.240 replaced the enumerated-verb approach entirely: any thread reply containing the standalone word "above" + a scheduling trigger now resolves via the existing pronoun-reference context-enrichment mechanism (`ABOVE_REFERENCE_PATTERN`), no verb list to maintain. Also built `scripts/reminder-thread-battery.js` — an interactive turn-by-turn test harness (real `RemindersModule`/`WorkspaceAI` via `MockSlackApp.SimulateMessageAsync`, since `slack-harness-post.js` can''t reach this code path at all due to Slack Bolt''s `ignoreSelf` default). Headless Codex review (`relay-xyz`) of that work then caught a real blocker in the harness itself (crashed under its own documented plain-`node` invocation — missing jest shim) plus 2 hygiene gaps (silent green-exit on a turn error, incomplete/collision-prone cleanup); all fixed in v1.4.241. 23 new regression tests total across both phases. → [PROJECT/3-COMPLETED/GH-424-ABOVE-CONTEXT-SYNTHESIS.md](PROJECT/3-COMPLETED/GH-424-ABOVE-CONTEXT-SYNTHESIS.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRY2VRYVEK3GYT5EX16', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'First-responder workspace awareness (GH-405)', 'Completed', '15', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-405-FIRST-RESPONDER-WORKSPACE-SNAPSHOT.md', NULL, '- **First-responder workspace awareness (GH-405)** — **#397 follow-on, shipped v1.4.234 (PR [#409](https://github.com/NeochromeTeam/sleuth-app/pull/409), merged to development 2026-07-17).** Gives the Flash-Lite router a cached, token-bounded per-workspace snapshot (`openTotal` + top-5 clients by open count) injected into its RMM context, and — in `active` mode — a deterministic "how many open for &lt;client&gt;?" answer recomputed **live** from `GetAllReminders()`. **Doubly gated** (`ROUTER_SNAPSHOT_ENABLED` default off **and** router armed) → dormant on prod. `projectId` null in v1 so projects omitted; week-completions deferred (Phase 0). Independent cross-model `/consult` (codex + agy) applied — the deterministic count now reuses ask-reminders'' canonical fail-closed privacy helpers and declines on any unresolved-privacy or time/assignee scope. Issue [#405](https://github.com/NeochromeTeam/sleuth-app/issues/405). → [PROJECT/3-COMPLETED/GH-405-FIRST-RESPONDER-WORKSPACE-SNAPSHOT.md](PROJECT/3-COMPLETED/GH-405-FIRST-RESPONDER-WORKSPACE-SNAPSHOT.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYVNNWA1WDFX073X3C', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Friendlier CHANGELOG entries (GH-408)', 'Completed', '16', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-408-CHANGELOG-FRIENDLY-TONE.md', NULL, '- **Friendlier CHANGELOG entries (GH-408)** — **shipped to development.** Both Slack surfaces (the `changelog` command + deploy startup message) read less mechanically now that `CHANGELOG.md` leads each entry with a friendly first-person plain-language TL;DR then a `**Technical:**` block. **Phase 1 (v1.4.232):** top-of-file authoring note (above the first `## ` so the Slack extractor ignores it) + 1.4.232 reformatted as the exemplar. **Phase 2 (v1.4.233):** `scripts/validate-changelog-tone.js` + `validate:changelog-tone` guard (mirrors `validate-reminder-render.js`) enforced under `npm test` — fails a bullet-first / no-`Technical:` newest block; forward-only; `<!-- TONE-OK: -->` pragma. Issue [#408](https://github.com/NeochromeTeam/sleuth-app/issues/408). → [PROJECT/3-COMPLETED/GH-408-CHANGELOG-FRIENDLY-TONE.md](PROJECT/3-COMPLETED/GH-408-CHANGELOG-FRIENDLY-TONE.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYYTB38TV5B4HVWCW2', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Richer reminder Q&A (GH-367)', 'Completed', '17', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-367-RICHER-REMINDER-QUERIES.md', NULL, '- **Richer reminder Q&A (GH-367)** — extends `ask-reminders` into deterministic time/user/client/keyword queries via a transport-neutral query core (`src/reminder-query-engine.js`), reused by a local `talk-to-reminders` Claude Code skill. **Phase 1 (Slack v1)** shipped 1.4.213 (PR #370) — parse → assemble → filter (privacy→time→user→client) → short-circuit-on-empty → model phrases only, `SlackApp.IsChannelPrivateAsync` fail-closed. **Phase 2 (export enrichment: `clientId` + bounded `completions-<ws>.json`)** + **Phase 3 (local zero-network skill)** shipped 1.4.214. **Last QA-gate item (ambiguous client first-match, regression-tested in `client-mapping.test.js`) closed 2026-07-17 in v1.4.235 — issue closed.** Plan refined by Codex+agy `/consult`, privacy elevated to a v1 MUST. Deferred: per-workspace client-mapping migration (**#369**); local `--client` needs the server to republish the enriched export. → [PROJECT/3-COMPLETED/GH-367-RICHER-REMINDER-QUERIES.md](PROJECT/3-COMPLETED/GH-367-RICHER-REMINDER-QUERIES.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYQE2EE32JJ00S0CR8', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Command-catalog gap: `confirm-multi-task-proposal` (GH-365)', 'Completed', '18', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-365-COMMAND-CATALOG-GAP.md', NULL, '- **Command-catalog gap: `confirm-multi-task-proposal` (GH-365)** — `validate:commands` was red on `main`/`development` since GH-360 wired the route without a matching catalog entry. Fixed 2026-07-17 in v1.4.235; uncovered (not fixed) a second pre-existing validator gap (`ask-reminders` synthetic entry vs. dynamic registration, **#410**) and a suspicious cross-workspace prototype-monkeypatch in `command-catalog.js` (**#411**) — both filed for separate review. Issue closed. → [PROJECT/3-COMPLETED/GH-365-COMMAND-CATALOG-GAP.md](PROJECT/3-COMPLETED/GH-365-COMMAND-CATALOG-GAP.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRY01AJFXDKQQ9EHZ48', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Reminder-render primitive (GH-391)', 'Completed', '19', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-391-REMINDER-RENDER-PRIMITIVE.md', NULL, '- **Reminder-render primitive (GH-391)** — a second convention-drift incident: `what''s open for Client A?` (ask-reminders query path) rendered a **custom text blob with raw `id:fc3d9b07` debug prefixes** instead of the canonical per-reminder individual reactable messages. **Phase 1 shipped 1.4.225** (individual ✅/🗑-reactable messages, no id-blob); **Phase 2 shipped 1.4.226** (documented primitive in AGENTS.md §0.1 + `validate-reminder-render.js` CI guard enforced under `npm test`). Both phases complete; issue reconciled + closed 2026-07-17 (PDDA sweep). → [PROJECT/3-COMPLETED/GH-391-REMINDER-RENDER-PRIMITIVE.md](PROJECT/3-COMPLETED/GH-391-REMINDER-RENDER-PRIMITIVE.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYS20WEV29G2S4AQMV', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'NaN completion timestamp bypasses time-window filter (GH-393)', 'Completed', '20', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-393-NAN-TIMESTAMP-FILTER.md', NULL, '- **NaN completion timestamp bypasses time-window filter (GH-393)** — `FilterCandidates`''s time-window guard treated `NaN` as a valid number (`typeof NaN === ''number''`), letting malformed completions (missing `completedMs`) leak into every time-scoped `ask-reminders` query. Found via the GH-391 cross-model `/consult`. Fixed 2026-07-17 in v1.4.235, regression-tested. Issue closed. → [PROJECT/3-COMPLETED/GH-393-NAN-TIMESTAMP-FILTER.md](PROJECT/3-COMPLETED/GH-393-NAN-TIMESTAMP-FILTER.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYKRZWB4YGRMSWWT7J', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Missing/blank `Candidate.title` guard (GH-399)', 'Completed', '21', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-399-CANDIDATE-TITLE-GUARD.md', NULL, '- **Missing/blank `Candidate.title` guard (GH-399)** — a confirm-multi-task-proposal candidate with a missing/blank AI-synthesized title could leak `undefined`/empty text into a persisted reminder. Fixed 2026-07-17 in v1.4.235 — candidates with no usable title are now skipped (logged) rather than scheduled, mirroring the existing duplicate-skip idiom. Issue closed. → [PROJECT/3-COMPLETED/GH-399-CANDIDATE-TITLE-GUARD.md](PROJECT/3-COMPLETED/GH-399-CANDIDATE-TITLE-GUARD.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRY88ZV1G3P1SF371PD', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Sleuth hardening marathon (GH-383 + GH-387 + GH-388)', 'Completed', '22', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-383-CHANNEL-PRIVACY-CACHE.md', NULL, '- **Sleuth hardening marathon (GH-383 + GH-387 + GH-388)** — three reliability lanes born from the #384 tenant-isolation incident: **p1 = #387** (CI guard that fails on globals-for-workspace-state / off-pattern route registration — `scripts/validate-workspace-isolation.js`, `npm run validate:workspace-isolation`), **p2 = #383** (channel-privacy cache + UNRESOLVED surfacing, 1.4.223), **p3 = #388** (no silent failures in ask-reminders, 1.4.224). **All three shipped** (found during a full PDDA doc-hygiene sweep 2026-07-17 — docs/issues had never been reconciled after the marathon actually shipped them; all 3 issues closed, docs moved to `3-COMPLETED`). → [GH-383](PROJECT/3-COMPLETED/GH-383-CHANNEL-PRIVACY-CACHE.md) · [GH-387](PROJECT/3-COMPLETED/GH-387-WORKSPACE-ISOLATION-GUARD.md) · [GH-388](PROJECT/3-COMPLETED/GH-388-NO-SILENT-FAILURES.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYZ5WF305J0JJD1QS4', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Reminder task-text quality (GH-337)', 'Completed', '23', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-337-REMINDER-TASK-TEXT.md', NULL, '- **Reminder task-text quality (GH-337)** — stop dumping long FYI notes verbatim; synthesize the buried task (two-segment length-aware settings) + unify digest display; folds #193/#3/#29. **All 4 phases shipped** (Phase 3 landed 1.4.209, commit 500470a — found undocumented during a 2026-07-09 marathon preflight sweep; CHANGELOG backfilled). #339 tracks separate non-blocking follow-ups. Doc/issue reconciled 2026-07-17 (PDDA sweep) — issue closed, doc moved to `3-COMPLETED`. → [PROJECT/3-COMPLETED/GH-337-REMINDER-TASK-TEXT.md](PROJECT/3-COMPLETED/GH-337-REMINDER-TASK-TEXT.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRY4ZRTD3HJCQKN6HHV', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Task bucketing (P2-TASK-BUCKETING)', 'Completed', '24', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/P2-TASK-BUCKETING.md', NULL, '- **Task bucketing (P2-TASK-BUCKETING)** — client/project inference over reminders; spike complete + `show-me-projects` Phase 1 shipped (1.4.161); remaining phases become a projection under P3 — this doc''s own scope is done. Moved to `3-COMPLETED` 2026-07-17 (PDDA sweep). → [PROJECT/3-COMPLETED/P2-TASK-BUCKETING.md](PROJECT/3-COMPLETED/P2-TASK-BUCKETING.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYPCHY5W4V2TX472SD', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'show-me reactable output (GH-338)', 'Completed', '25', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-338-SHOWME-COMMAND.md', NULL, '- **show-me reactable output (GH-338)** — make `show-me` post each ranked reminder as its own checkmark-closable, permalinked message (reuses the `show reminders` renderer) instead of one consolidated text blob; top 5, bucketed by due date, AI rationale appended per item. Shipped 1.4.209 (commit `2c8ee7d`, 2026-07-03) — found already-implemented-but-undocumented during the 2026-07-09 marathon run; codex added regression test coverage rather than duplicating working code, agy reviewed + approved, full suite green (1201/1201). Unblocks First-time-user UX Phase 1 (was serialized behind this on the reminder-display collision cluster). → [PROJECT/3-COMPLETED/GH-338-SHOWME-COMMAND.md](PROJECT/3-COMPLETED/GH-338-SHOWME-COMMAND.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYSPWB9ADVFWHV8RWX', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Adopt Blend philosophy into GUIDING-PRINCIPLES.md (GH-348)', 'Completed', '26', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-348-ADOPT-BLEND-PHILOSOPHY.md', NULL, '- **Adopt Blend philosophy into GUIDING-PRINCIPLES.md (GH-348)** — gradiated 2-phase merge of `AGENTS-PROPOSED.md` into a new "Engineering Philosophy" section in `GUIDING-PRINCIPLES.md` (amended 2026-07-03, was `AGENTS.md`); reconciled comment format + carved out the DI/seam rule as an accepted test-suite exception (not refactored) before landing. Built via the marathon swarm (codex builder + agy reviewer) 2026-07-09, `npm test` green (1200/1200). → [PROJECT/3-COMPLETED/GH-348-ADOPT-BLEND-PHILOSOPHY.md](PROJECT/3-COMPLETED/GH-348-ADOPT-BLEND-PHILOSOPHY.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYKXY02YEKR62ZAW3G', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Hyphen/space command normalization (GH-349)', 'Completed', '27', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-349-HYPHEN-COMMAND-NORMALIZATION.md', NULL, '- **Hyphen/space command normalization (GH-349)** — auto-derive hyphen↔space tolerance for argument-invariant commands from `BuildCanonicalCommand`''s existing canonical-string switch (`Proxy`-sentinel invariance check), instead of hand-writing more regexes; design reviewed + approved via 2-round Agy relay (2026-07-03), catches optionally argument-bearing commands (`search-projects`, `test-github-sync`) that a naive heuristic would have missed. Shipped 1.4.211 (commit `d91f7ed`, via marathon automation 2026-07-07) — both phases landed, redundant hand-written regexes removed. Issue #349 closed; found undocumented during a 2026-07-09 marathon preflight sweep. → [PROJECT/3-COMPLETED/GH-349-HYPHEN-COMMAND-NORMALIZATION.md](PROJECT/3-COMPLETED/GH-349-HYPHEN-COMMAND-NORMALIZATION.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRYBV5SVMQZAZK5AY8N', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Flaky fixed-port test (GH-351)', 'Completed', '28', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-351-FLAKY-PORT-TEST.md', NULL, '- **Flaky fixed-port test (GH-351)** — `tests/web-api-workspace.test.js` hardcoded port `19877`; parallel/leftover-process collisions threw `EADDRINUSE` and failed 3 cases intermittently. Shipped 1.4.211 (commit `578b3e7`, via marathon automation 2026-07-06) — ephemeral OS-assigned port (`TestPort = 0`). Issue #351 closed; found undocumented during a 2026-07-09 marathon preflight sweep. → [PROJECT/3-COMPLETED/GH-351-FLAKY-PORT-TEST.md](PROJECT/3-COMPLETED/GH-351-FLAKY-PORT-TEST.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRZC6CZZQ0RS2Y3KCT8', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Trim AGENTS.md''s redundant inventory (GH-352)', 'Completed', '29', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-352-TRIM-AGENTS-MD.md', NULL, '- **Trim AGENTS.md''s redundant inventory (GH-352)** — removed §4 (Data Persistence), §5 (Web API Contract Checklist), and §11 (Architecture And Key Paths) from `AGENTS.md`, replacing each with a one-line pointer to its still-current canonical home (`ARCHITECTURE.md`, `docs/web-api.md`, `ARCHITECTURE-DECISIONS.md`); trimmed §12 to just the Process Environment Flags subsection (workspace field tables now point to `src/workspaces.js`). `AGENTS.md` 395 → 305 lines, no information loss. `ROUTER.md` pointers updated to match. Built via the marathon swarm (codex builder + agy reviewer) 2026-07-09, `npm test` green (1200/1200). → [PROJECT/3-COMPLETED/GH-352-TRIM-AGENTS-MD.md](PROJECT/3-COMPLETED/GH-352-TRIM-AGENTS-MD.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRZYA09YG2XXNP4Q226', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'P3 Phase 2 baseline-import (GH-355)', 'Completed', '30', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-355-P3-BASELINE-IMPORT.md', NULL, '- **P3 Phase 2 baseline-import (GH-355)** — one-shot idempotent import emitting `BaselineReminderImported` events for pre-ledger reminders (both active + completed stores), fixing the null assignee/sourceChannel gap in the `summarize-week` projection fold; also fixed the fold''s `githubUrls` mapping gap. Prod-validated: shadow-diff on real `neochrome` data went from 11 null-field mismatches to 0 — 1.4.211 (`b3075d7`). Cutover sequence steps 1–2 done; the flag flip itself (`SUMMARIZE_WEEK_COMPLETED_SOURCE=projection`) stays a separate, human-gated decision. → [PROJECT/3-COMPLETED/GH-355-P3-BASELINE-IMPORT.md](PROJECT/3-COMPLETED/GH-355-P3-BASELINE-IMPORT.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRZBX2YGDBAVQT1WKYJ', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'ask-self ingest architecture-summary fix (GH-347)', 'Completed', '31', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-347-ASK-SELF-GRAPH-INTEGRATION.md', NULL, '- **ask-self ingest architecture-summary fix (GH-347)** — fixed two silent bugs found via `codebase-memory-mcp` graph research: the module inventory missed `src/chat-commands/` (28 files), `src/ai-providers/`, and `src/plugins/`; the command feature-map matched zero real commands (stale pre-CommandRouter regex). Now recursive + catalog-sourced + real HTTP routes — 1.4.209. Function-boundary-aware chunking and query-time hybrid retrieval deferred (higher effort/coupling). → [PROJECT/3-COMPLETED/GH-347-ASK-SELF-GRAPH-INTEGRATION.md](PROJECT/3-COMPLETED/GH-347-ASK-SELF-GRAPH-INTEGRATION.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
