INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRZXJJCEA5BSCHX36CE', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Admin `send to github` command (GH-341)', 'Completed', '34', NULL, NULL, NULL, NULL, NULL, NULL, '- **Admin `send to github` command (GH-341)** — workspace admins can file a GitHub issue from a Slack thread (`@Sleuth AI send to github`) with the transcript, permalink, and metadata as evidence — 1.4.206 (PR #343). → [CHANGELOG.md](CHANGELOG.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRZ8KP562D25C6JN7MB', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Command routing hardening', 'Completed', '35', NULL, NULL, NULL, NULL, NULL, NULL, '- **Command routing hardening** — `remember above` now only fires as a standalone command, not when a message merely mentions the phrase (asking *about* it via `ask-self` no longer triggers a write) — 1.4.204. → [CHANGELOG.md](CHANGELOG.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
