INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0XWWTRZBYRW4TG9DCT57GJC', 'repo-01M0V7B2N4NR2AFQPFYKVT7997', NULL, 'Command Near-Miss Recovery', 'Completed', '39', NULL, NULL, NULL, NULL, 'PROJECT/3-COMPLETED/COMMAND-NEAR-MISS-AI-FALLBACK.md', NULL, '- **Command Near-Miss Recovery** — Phase 0 (miss counter) + Phase 1 ("I Feel Lucky" alias) shipped 1.4.199/1.4.200. **Phase 0 counter READOUT 2026-07-05 (gate resolved):** only 2 near-misses in 6 weeks on prod `neochrome` (scores 9, 4) → too sparse to re-set the score floor (provisional 5 stands), rate too low to justify LLM tiers. **Phase 2-full/3/4 HELD — do not build**; **Phase 2-lite flipped ON on prod 2026-07-06** (`COMMAND_NEAR_MISS_LITE=ON`) — free deterministic "Did you mean?" + thickens the dataset. Doc moved to `3-COMPLETED` 2026-07-17 (PDDA sweep) — this is a settled decision endpoint, not abandoned. → [PROJECT/3-COMPLETED/COMMAND-NEAR-MISS-AI-FALLBACK.md](PROJECT/3-COMPLETED/COMMAND-NEAR-MISS-AI-FALLBACK.md)', '2026-08-26T02:02:58Z', '2026-08-26T02:02:58Z', NULL, NULL, NULL, NULL, NULL);
